<?php
/** Power BI: getting and shaping data with Power Query, the data model and relationships, DAX measures, reports and sharing. */

return [
    'id' => 'powerbi', 'family' => 'powerbi', 'after' => 'excel',
    'title' => L('Power BI', 'Power BI'), 'short' => L('Power BI', 'Power BI'), 'level' => L('Base', 'Basics'),
    'desc' => L('Dai dati ai cruscotti: importare e pulire con Power Query, modello dati e relazioni, misure DAX, report interattivi e condivisione.', 'From data to dashboards: importing and cleaning with Power Query, data model and relationships, DAX measures, interactive reports and sharing.'),
    'lessons' => [
        lesson('query', L('Importare e pulire i dati', 'Importing and cleaning data'), [
            P('**Power BI** di Microsoft trasforma dati sparsi (Excel, CSV, database, servizi online) in report interattivi. Si lavora in **Power BI Desktop** e si pubblica sul **servizio Power BI** online. Il primo passo è **Recupera dati** e poi **Power Query**, l’editor per pulire e trasformare.', 'Microsoft’s **Power BI** turns scattered data (Excel, CSV, databases, online services) into interactive reports. You work in **Power BI Desktop** and publish to the online **Power BI service**. The first step is **Get data** and then **Power Query**, the editor to clean and transform.'),
            P('In Power Query si rimuovono colonne inutili, si impostano i **tipi** giusti (data, numero, testo), si tolgono doppioni e righe vuote, si dividono colonne, si uniscono tabelle. Ogni passaggio viene **registrato**: al prossimo aggiornamento dei dati, Power BI ripete tutto da solo.', 'In Power Query you remove useless columns, set the right **types** (date, number, text), remove duplicates and empty rows, split columns, merge tables. Each step is **recorded**: on the next data refresh, Power BI repeats everything by itself.'),
            Tip('Pulisci i dati in Power Query, non a mano nel file di origine: così l’aggiornamento successivo resta automatico.', 'Clean data in Power Query, not by hand in the source file: that way the next refresh stays automatic.'),
        ], [
            Q('q1', L('A che cosa serve Power Query?', 'What is Power Query for?'), [L('Pulire e trasformare i dati prima dell’analisi', 'Cleaning and transforming data before analysis'), L('Disegnare loghi', 'Drawing logos'), L('Inviare email', 'Sending email'), L('Scrivere documenti', 'Writing documents')], 0, L('L’editor delle trasformazioni.', 'The transformation editor.')),
            Q('q2', L('Che cosa succede ai passaggi di Power Query quando aggiorni i dati?', 'What happens to Power Query steps when you refresh data?'), [L('Vengono ripetuti automaticamente', 'They are repeated automatically'), L('Si perdono', 'They are lost'), L('Vanno rifatti a mano', 'They must be redone by hand'), L('Si cancellano i dati', 'Data is deleted')], 0, L('Tutto registrato.', 'All recorded.')),
            Q('q3', L('Dove si crea un report di solito?', 'Where is a report usually built?'), ['Power BI Desktop', 'Paint', 'Outlook', L('Il blocco note', 'Notepad')], 0, L('Poi si pubblica online.', 'Then published online.')),
        ], task('text', L('Elenca quattro pulizie tipiche da fare in Power Query su un file di vendite, una per riga con `-`, tra cui una sui **tipi** delle colonne.', 'List four typical clean-ups to do in Power Query on a sales file, one per line with `-`, including one about column **types**.'), "- \n- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Quattro pulizie', 'Four clean-ups')), re('tip[oi]|type|data|date|numer', L('Una sui tipi', 'One about types'))], '', "- impostare il tipo data sulla colonna Data\n- rimuovere le colonne inutili\n- togliere i doppioni\n- eliminare le righe vuote"), [
            dOrder(pSort(), [L('Recupera dati', 'Get data'), L('Pulisci in Power Query', 'Clean in Power Query'), L('Crea il modello e le relazioni', 'Build the model and relationships'), L('Scrivi le misure DAX', 'Write DAX measures'), L('Costruisci il report e pubblica', 'Build the report and publish')], L('Il percorso di un report.', 'A report’s journey.')),
            dMatch(pMatch(), [[L('Recupera dati', 'Get data'), L('Collegarsi alle fonti', 'Connecting to sources')], ['Power Query', L('Pulire e trasformare', 'Clean and transform')], [L('Tipo di dato', 'Data type'), L('Data, numero, testo', 'Date, number, text')], [L('Aggiornamento', 'Refresh'), L('Ripete i passaggi', 'Repeats the steps')]], L('Preparare i dati.', 'Preparing data.')),
        ]),
        lesson('model', L('Modello dati e relazioni', 'Data model and relationships'), [
            P('Un buon report nasce da un buon **modello dati**. Lo schema consigliato è lo **schema a stella**: al centro una **tabella dei fatti** (le vendite: data, prodotto, cliente, importo), intorno le **tabelle dimensione** (Prodotti, Clienti, Calendario) collegate da **relazioni** uno-a-molti.', 'A good report comes from a good **data model**. The recommended layout is the **star schema**: in the centre a **fact table** (sales: date, product, customer, amount), around it **dimension tables** (Products, Customers, Calendar) connected by one-to-many **relationships**.'),
            C('            Prodotti (1)
                 │
Clienti (1) ── Vendite (*) ── Calendario (1)
                 │
            Negozi (1)', 'text'),
            P('Una tabella **Calendario** con tutte le date (anno, mese, trimestre, giorno della settimana) è quasi sempre necessaria per analizzare l’andamento nel tempo. Le relazioni permettono di filtrare le vendite scegliendo un prodotto, un cliente o un mese.', 'A **Calendar** table with every date (year, month, quarter, weekday) is almost always needed to analyse trends over time. Relationships let you filter sales by choosing a product, a customer or a month.'),
        ], [
            Q('m1', L('Che cosa c’è al centro di uno schema a stella?', 'What sits at the centre of a star schema?'), [L('La tabella dei fatti', 'The fact table'), L('La tabella dei colori', 'The colour table'), L('Un grafico', 'A chart'), L('Niente', 'Nothing')], 0, L('Le dimensioni intorno.', 'Dimensions around it.')),
            Q('m2', L('Che tipo di relazione collega Prodotti e Vendite?', 'What relationship type links Products and Sales?'), [L('Uno-a-molti', 'One-to-many'), L('Molti-a-molti sempre', 'Always many-to-many'), L('Nessuna', 'None'), L('Uno-a-uno sempre', 'Always one-to-one')], 0, L('Un prodotto, tante vendite.', 'One product, many sales.')),
            Q('m3', L('Perché serve una tabella Calendario?', 'Why is a Calendar table needed?'), [L('Per analizzare l’andamento nel tempo', 'To analyse trends over time'), L('Per le ferie', 'For holidays'), L('Per i compleanni', 'For birthdays'), L('Non serve', 'It is not needed')], 0, L('Anno, mese, trimestre…', 'Year, month, quarter…')),
        ], task('text', L('Indica per ciascuna tabella se è `fatti` o `dimensione`, una per riga come `tabella: tipo`: `Vendite`, `Prodotti`, `Calendario`.', 'For each table say whether it is `fact` or `dimension`, one per line as `table: type`: `Vendite`, `Prodotti`, `Calendario`.'), '', [re('Vendite\s*:\s*(fatti|fact)', L('Vendite = fatti', 'Sales = fact')), re('Prodotti\s*:\s*(dimensione|dimension)', L('Prodotti = dimensione', 'Products = dimension')), re('Calendario\s*:\s*(dimensione|dimension)', L('Calendario = dimensione', 'Calendar = dimension'))], '', "Vendite: fatti\nProdotti: dimensione\nCalendario: dimensione"), [
            dMatch(pMatch(), [[L('Tabella dei fatti', 'Fact table'), L('Eventi e importi', 'Events and amounts')], [L('Tabella dimensione', 'Dimension table'), L('Chi, cosa, quando', 'Who, what, when')], [L('Uno-a-molti', 'One-to-many'), L('Relazione tipica', 'Typical relationship')], [L('Calendario', 'Calendar'), L('Analisi nel tempo', 'Time analysis')], [L('Schema a stella', 'Star schema'), L('Modello consigliato', 'Recommended model')]], L('Modellare i dati.', 'Modelling data.')),
            dFlash(pFlash(), [[L('Lo schema a stella ha una tabella dei fatti al centro', 'The star schema has a fact table at the centre'), true], [L('Una tabella unica con tutto è sempre meglio', 'One table with everything is always better'), false], [L('Le relazioni permettono di filtrare tra tabelle', 'Relationships allow filtering across tables'), true], [L('La tabella Calendario è inutile', 'The Calendar table is useless'), false]], L('Fondamenta solide.', 'Solid foundations.')),
        ]),
        lesson('dax', L('Misure DAX', 'DAX measures'), [
            P('**DAX** è il linguaggio delle formule di Power BI. Le **misure** calcolano valori aggregati che cambiano con i filtri del report (totale vendite, margine, crescita). I nomi delle funzioni DAX sono in inglese anche nella versione italiana.', '**DAX** is Power BI’s formula language. **Measures** compute aggregated values that change with the report’s filters (total sales, margin, growth). DAX function names are in English even in the Italian version.'),
            C('Vendite Totali = SUM(Vendite[Importo])
Numero Ordini = DISTINCTCOUNT(Vendite[IdOrdine])
Scontrino Medio = DIVIDE([Vendite Totali], [Numero Ordini])
Vendite Nord = CALCULATE([Vendite Totali], Negozi[Regione] = "Nord")
Vendite Anno Prec = CALCULATE([Vendite Totali], SAMEPERIODLASTYEAR(Calendario[Data]))', 'dax'),
            P('**`CALCULATE`** è la funzione più importante: calcola una misura cambiando i filtri. `DIVIDE` divide evitando gli errori di divisione per zero. Preferisci le **misure** alle colonne calcolate per i totali: si adattano a qualsiasi filtro e occupano meno memoria.', '**`CALCULATE`** is the most important function: it computes a measure while changing the filters. `DIVIDE` divides avoiding division-by-zero errors. Prefer **measures** to calculated columns for totals: they adapt to any filter and use less memory.'),
        ], [
            Q('d1', L('Che cosa fa CALCULATE?', 'What does CALCULATE do?'), [L('Calcola una misura cambiando i filtri', 'Computes a measure while changing filters'), L('Somma due numeri', 'Adds two numbers'), L('Crea una tabella', 'Creates a table'), L('Ordina i dati', 'Sorts data')], 0, L('Il cuore di DAX.', 'The heart of DAX.')),
            Q('d2', L('Perché usare DIVIDE invece di /?', 'Why use DIVIDE instead of /?'), [L('Gestisce la divisione per zero', 'It handles division by zero'), L('È più veloce sempre', 'It is always faster'), L('È obbligatorio', 'It is mandatory'), L('Non c’è motivo', 'There is no reason')], 0, L('Niente errori nei visual.', 'No errors in visuals.')),
            Q('d3', L('Le funzioni DAX hanno nomi italiani nella versione italiana?', 'Do DAX functions have Italian names in the Italian version?'), [L('No, restano in inglese', 'No, they stay in English'), L('Sì, sempre', 'Yes, always'), L('Solo SUM', 'Only SUM'), L('Dipende dal giorno', 'It depends on the day')], 0, L('A differenza di Excel.', 'Unlike Excel.')),
        ], task('dax', L('Scrivi la misura `Vendite Online = CALCULATE([Vendite Totali], Vendite[Canale] = "Online")`.', 'Write the measure `Vendite Online = CALCULATE([Vendite Totali], Vendite[Canale] = "Online")`.'), '', [re('^\s*Vendite Online\s*=\s*CALCULATE\s*\(\s*\[Vendite Totali\]\s*,\s*Vendite\[Canale\]\s*=\s*"Online"\s*\)', L('La misura con filtro', 'The filtered measure'))], '', 'Vendite Online = CALCULATE([Vendite Totali], Vendite[Canale] = "Online")'), [
            dMatch(pMatch(), [['SUM', L('Somma una colonna', 'Sums a column')], ['DISTINCTCOUNT', L('Conta i valori distinti', 'Counts distinct values')], ['DIVIDE', L('Divisione sicura', 'Safe division')], ['CALCULATE', L('Cambia i filtri', 'Changes filters')], ['SAMEPERIODLASTYEAR', L('Stesso periodo anno prima', 'Same period last year')]], L('Le funzioni DAX.', 'DAX functions.')),
            dBug(pBug(), ['Vendite Totali = SUM(Vendite[Importo])', 'Margine % = [Margine] / [Vendite Totali]'], 1, 'Margine % = DIVIDE([Margine], [Vendite Totali])', L('Con / un mese senza vendite dà errore: usa DIVIDE.', 'With / a month without sales errors out: use DIVIDE.')),
        ]),
        lesson('report', L('Report e condivisione', 'Reports and sharing'), [
            P('Un report è fatto di **visual** (grafici, tabelle, schede con un numero, mappe) e **filtri dei dati** (slicer) che l’utente usa per esplorare. Cliccando su un grafico si filtrano gli altri: è l’**interattività** che distingue un report da un foglio statico.', 'A report is made of **visuals** (charts, tables, single-number cards, maps) and **slicers** the user uses to explore. Clicking on one chart filters the others: this **interactivity** sets a report apart from a static sheet.'),
            P('Buone pratiche: in alto i numeri chiave (schede), poi gli andamenti, poi i dettagli; pochi colori coerenti; titoli che dicono la conclusione (“Le vendite online crescono del 18%”). Si pubblica sul servizio Power BI, si pianifica l’**aggiornamento automatico** e si condivide con i colleghi; la **sicurezza a livello di riga** (RLS) fa vedere a ciascuno solo i propri dati (per esempio la sua regione).', 'Good practice: key numbers at the top (cards), then trends, then details; few consistent colours; titles stating the conclusion (“Online sales grow 18%”). You publish to the Power BI service, schedule **automatic refresh** and share with colleagues; **row-level security** (RLS) lets each person see only their own data (for example their region).'),
        ], [
            Q('r1', L('Che cos’è uno slicer?', 'What is a slicer?'), [L('Un filtro visivo che l’utente usa nel report', 'A visual filter the user uses in the report'), L('Un tipo di torta', 'A kind of pie'), L('Un errore', 'An error'), L('Un file', 'A file')], 0, L('Per esplorare i dati.', 'To explore data.')),
            Q('r2', L('Che cosa fa la sicurezza a livello di riga?', 'What does row-level security do?'), [L('Mostra a ciascuno solo i propri dati', 'Shows each person only their own data'), L('Cifra il computer', 'Encrypts the computer'), L('Cancella le righe', 'Deletes rows'), L('Blocca il report', 'Locks the report')], 0, L('Per regione, reparto…', 'By region, department…')),
            Q('r3', L('Che cosa mettere in alto in un report?', 'What goes at the top of a report?'), [L('I numeri chiave', 'The key numbers'), L('I dettagli di ogni riga', 'Every row’s details'), L('Il logo enorme', 'A huge logo'), L('Niente', 'Nothing')], 0, L('Poi andamenti e dettagli.', 'Then trends and details.')),
        ], task('text', L('Progetta la pagina di un report vendite: tre righe che iniziano con `In alto:`, `Al centro:` e `In basso:`, indicando quali visual metteresti.', 'Design a sales report page: three lines starting with `Top:`, `Middle:` and `Bottom:`, saying which visuals you would place.'), "In alto: \nAl centro: \nIn basso: ", [re('^(In alto|Top):\s*.*(schede|cards?|numer|KPI|totale|total)', L('In alto i numeri chiave', 'Key numbers at the top')), re('^(Al centro|Middle):\s*.*(linee|line|andament|trend|grafic|chart)', L('Al centro gli andamenti', 'Trends in the middle')), re('^(In basso|Bottom):\s*.*(tabella|table|dettagl|detail)', L('In basso i dettagli', 'Details at the bottom'))], '', "In alto: schede con vendite totali, numero ordini e scontrino medio\nAl centro: grafico a linee dell’andamento mensile\nIn basso: tabella con il dettaglio per prodotto"), [
            dMatch(pMatch(), [[L('Scheda', 'Card'), L('Un numero chiave', 'A key number')], ['Slicer', L('Filtro interattivo', 'Interactive filter')], [L('Grafico a linee', 'Line chart'), L('Andamento', 'Trend')], ['RLS', L('Dati per persona', 'Data per person')], [L('Aggiornamento pianificato', 'Scheduled refresh'), L('Dati sempre freschi', 'Always fresh data')]], L('Report che parlano.', 'Reports that speak.')),
            dFlash(pFlash(), [[L('Cliccare su un grafico può filtrare gli altri', 'Clicking a chart can filter the others'), true], [L('Più colori diversi rendono il report più chiaro', 'More different colours make the report clearer'), false], [L('Un titolo può dire la conclusione', 'A title can state the conclusion'), true], [L('Un report pubblicato non si può aggiornare', 'A published report cannot be refreshed'), false]], L('Dai numeri alle decisioni.', 'From numbers to decisions.')),
        ]),
        lesson('time-security', L('Intelligenza temporale e sicurezza delle righe', 'Time intelligence and row-level security'), [
            P('Per confronti nel tempo serve una **tabella calendario** collegata ai fatti e segnata come tabella di date. Poi le funzioni di **intelligenza temporale** calcolano da inizio anno, l’anno precedente, la crescita.', 'For comparisons over time you need a **calendar table** linked to the facts and marked as a date table. Then **time intelligence** functions compute year-to-date, previous year, growth.'),
            C('Vendite YTD = TOTALYTD([Vendite totali], Calendario[Data])
Vendite anno prec. = CALCULATE([Vendite totali], SAMEPERIODLASTYEAR(Calendario[Data]))
Crescita % = DIVIDE([Vendite totali] - [Vendite anno prec.], [Vendite anno prec.])', 'dax'),
            P('La **sicurezza a livello di riga** (RLS) mostra a ogni persona solo i suoi dati: si crea un ruolo con un filtro DAX (per esempio `[Regione] = "Nord"`) e si assegnano gli utenti al ruolo nel servizio Power BI. Si prova con “Visualizza come ruolo”.', '**Row-level security** (RLS) shows each person only their data: you create a role with a DAX filter (for example `[Region] = "North"`) and assign users to the role in the Power BI service. Test it with “View as role”.'),
        ], [
            Q('ts1', L('Che cosa serve per l’intelligenza temporale?', 'What is needed for time intelligence?'), [L('Una tabella calendario collegata', 'A linked calendar table'), L('Un grafico a torta', 'A pie chart'), L('Un file Excel', 'An Excel file'), L('Niente', 'Nothing')], 0, L('Segnata come tabella di date.', 'Marked as a date table.')),
            Q('ts2', L('Che cosa calcola `SAMEPERIODLASTYEAR`?', 'What does `SAMEPERIODLASTYEAR` compute?'), [L('Lo stesso periodo dell’anno prima', 'The same period last year'), L('L’anno prossimo', 'Next year'), L('La media mensile', 'The monthly average'), L('Il totale generale', 'The grand total')], 0, L('Dentro CALCULATE.', 'Inside CALCULATE.')),
            Q('ts3', L('A che cosa serve la RLS?', 'What is RLS for?'), [L('Mostrare a ognuno solo i suoi dati', 'Showing each person only their data'), L('Velocizzare i grafici', 'Speeding up charts'), L('Cambiare i colori', 'Changing colours'), L('Esportare in PDF', 'Exporting to PDF')], 0, L('Ruoli con filtri DAX.', 'Roles with DAX filters.')),
        ], task('dax', L('Scrivi la misura `Vendite YTD = TOTALYTD([Vendite totali], Calendario[Data])`.', 'Write the measure `Vendite YTD = TOTALYTD([Vendite totali], Calendario[Data])`.'), '', [re('^Vendite YTD\s*=\s*TOTALYTD\(\s*\[Vendite totali\]\s*,\s*Calendario\[Data\]\s*\)', L('La misura è giusta', 'The measure is right'))], '', 'Vendite YTD = TOTALYTD([Vendite totali], Calendario[Data])'), [
            dMatch(pMatch(), [['TOTALYTD', L('Da inizio anno', 'Year to date')], ['SAMEPERIODLASTYEAR', L('Anno precedente', 'Previous year')], ['DIVIDE', L('Divisione sicura', 'Safe division')], ['RLS', L('Dati per persona', 'Data per person')], [L('Tabella calendario', 'Calendar table'), L('Base delle date', 'Date foundation')]], L('Tempo e sicurezza.', 'Time and security.')),
            dFlash(pFlash(), [[L('DIVIDE evita l’errore di divisione per zero', 'DIVIDE avoids the divide-by-zero error'), true], [L('La RLS si prova con Visualizza come ruolo', 'RLS is tested with View as role'), true], [L('L’intelligenza temporale funziona senza date', 'Time intelligence works without dates'), false], [L('La RLS colora le righe della tabella', 'RLS colours table rows'), false]], L('Report affidabili.', 'Reliable reports.')),
        ]),
    ],
];
